/* e14ux8 compatibility patch: direct Mafia Boss handover during role reveal + clearer vote selection */
async function resignMafiaLeader(successor){
  if(!successor)return;
  const target=(game.me?.mafiaTeam||[]).find(function(p){return p.id===successor;});
  if(!target)return;
  if(!confirm(discussionText('تسليم قيادة المافيا إلى ','Transfer Mafia leadership to ')+target.name+'؟'))return;
  try{
    game=await api({action:'electMafiaLeader',code:game.code,id:playerId,playerToken,target:'RESIGN',successor:successor});
    renderPlayer();
  }catch{
    notice(discussionText('تعذر تسليم القيادة.','Could not transfer leadership.'));
  }
}
function leaderElectionCard(){
  if(!game?.me?.alive || game.phase!=='reveal')return '';
  if(game.me.leaderElection){
    const ended=Date.now()+discussionClockOffset>=game.me.leaderDeadline;
    return '<section id="leaderElectionCard" class="card" data-no-translate>'
      +'<h2>'+discussionText('اختيار زعيم المافيا الجديد','Choose the new Mafia Boss')+'</h2>'
      +'<p>'+discussionText('تصويت سري بعد التنازل. الأكثر أصواتًا يصبح الزعيم، والتعادل بقرعة.','Secret vote after resignation. Highest votes wins; ties are randomized.')+'</p>'
      +(ended
        ? '<button class="btn gold" onclick="electMafiaLeader(&quot;FINALIZE&quot;)">'+discussionText('حسم التصويت وتحديث الكروت','Finalize vote and refresh roles')+'</button>'
        : game.me.leaderVote
          ? '<p>'+discussionText('تم تسجيل صوتك. بانتظار بقية الفريق.','Your vote is saved. Waiting for the team.')+'</p>'
          : choiceButtons((game.me.mafiaTeam||[]).filter(function(p){return p.id!==game.me.leaderFormer&&p.alive!==false;}),'electMafiaLeader',{icon:'👑'}))
      +'</section>';
  }
  if(game.me.role!=='mafia_boss')return '';
  const successors=(game.me.mafiaTeam||[]).filter(function(p){
    return p.id!==game.me.id && game.players.some(function(x){return x.id===p.id&&x.alive;});
  });
  if(!successors.length)return '';
  return '<section id="leaderElectionCard" class="card" data-no-translate>'
    +'<h3>'+discussionText('👑 تسليم قيادة المافيا','👑 Transfer Mafia leadership')+'</h3>'
    +'<p>'+discussionText('اختر فرد المافيا الذي يستلم الرئاسة مباشرة قبل تأكيد دورك.','Choose the Mafia member who becomes Boss immediately before you confirm your role.')+'</p>'
    +successors.map(function(p){
      return '<button class="btn red wide" onclick="resignMafiaLeader('+jsArg(p.id)+')">👑 '+escapeHtml(p.name)+'</button>';
    }).join('')
    +'</section>';
}
function choiceButtons(players, action, options = {}) {
  const inner = players.map(function(player){
    const selected = action==='castVote' && game?.me?.voteTarget===player.id;
    return '<button class="pick'+(selected?' selected':'')+'" data-target="'+escapeHtml(player.id)+'" aria-pressed="'+(selected?'true':'false')+'" onclick="'+action+'('+jsArg(player.id)+')">'
      +(options.icon || '👤')+' '+escapeHtml(player.name)
      +(player.id===playerId?' ('+discussionText('أنت','You')+')':'')
      +(selected?' ✓':'')
      +'</button>';
  }).join('');
  return '<div class="choice-stack">'+inner+'</div>';
}
